#!/usr/bin/env bash
set -euo pipefail

cd "$(dirname "$0")/.."

# This is deliberately more restrictive than the integration test's guard: only a
# database name generated by this process can be removed by this script.
database="drift_cdg198_$(date +%s)_${RANDOM}_$$"
created=0

is_owned_name() {
    [[ "$database" =~ ^drift_cdg198_[0-9]+_[0-9]+_[0-9]+$ ]]
}

cleanup() {
    status=$?
    if [[ "$created" -eq 1 && "${KEEP_DB:-0}" != "1" ]]; then
        if is_owned_name; then
            docker compose exec -T postgres dropdb -U drift --if-exists "$database" \
                || echo "Warning: could not remove disposable database $database" >&2
        else
            echo "Refusing to remove unexpected database name: $database" >&2
        fi
    elif [[ "$created" -eq 1 ]]; then
        echo "Keeping disposable database $database (KEEP_DB=1)" >&2
    fi
    exit "$status"
}
trap cleanup EXIT

docker compose up -d postgres
for attempt in {1..30}; do
    if docker compose exec -T postgres pg_isready -U drift -d drift >/dev/null 2>&1; then
        break
    fi
    if [[ "$attempt" -eq 30 ]]; then
        echo "PostgreSQL did not become ready within 30 seconds" >&2
        exit 1
    fi
    sleep 1
done

is_owned_name || { echo "Refusing unexpected generated database name: $database" >&2; exit 1; }
docker compose exec -T postgres createdb -U drift "$database"
created=1

export CDG198_MIGRATION_DATABASE_URL="jdbc:postgresql://localhost:5432/$database"
export CDG198_MIGRATION_DATABASE_USERNAME=drift
export CDG198_MIGRATION_DATABASE_PASSWORD=drift

cd backend
bash ./mvnw -Dtest=ShipmentRiskAlertActivationMigrationIntegrationTest test
